#include <iostream>
#include <sstream>
#include <string>

bool leer_entero(const std::string& texto, int& destino) {
    std::istringstream campo{texto};
    int candidato{0};
    if (!(campo >> candidato)) {
        return false;
    }
    campo >> std::ws;
    if (!campo.eof() || campo.bad()) {
        return false;
    }
    destino = candidato;
    return true;
}

bool leer_registro(const std::string& linea, std::string& caso,
                   int& esperado, int& obtenido) {
    std::istringstream campos{linea};
    std::string caso_leido;
    std::string texto_esperado;
    std::string texto_obtenido;
    if (!(campos >> caso_leido >> texto_esperado >> texto_obtenido)) {
        return false;
    }
    campos >> std::ws;
    if (!campos.eof() || campos.bad()) {
        return false;
    }
    int esperado_leido{0};
    int obtenido_leido{0};
    if (!leer_entero(texto_esperado, esperado_leido)
        || !leer_entero(texto_obtenido, obtenido_leido)) {
        return false;
    }
    caso = caso_leido;
    esperado = esperado_leido;
    obtenido = obtenido_leido;
    return true;
}

int main() {
    std::string linea;
    int lineas{0};
    int validos{0};
    int coinciden{0};
    int difieren{0};
    int formato{0};
    bool hay_anterior{false};
    std::string caso_anterior;
    while (std::getline(std::cin, linea)) {
        ++lineas;
        std::string caso;
        int esperado{0};
        int obtenido{0};
        if (!leer_registro(linea, caso, esperado, obtenido)) {
            ++formato;
            std::cerr << "Line=" << lineas << ":FORMAT\n";
            continue;
        }
        if (hay_anterior && caso == caso_anterior) {
            continue;
        }
        hay_anterior = true;
        caso_anterior = caso;
        const bool coincide{esperado == obtenido};
        ++validos;
        if (coincide) {
            ++coinciden;
        } else {
            ++difieren;
        }
        std::cout << "Line=" << lineas << " Case=" << caso
                  << " Expected=" << esperado << " Actual=" << obtenido
                  << " " << (coincide ? "MATCH" : "DIFFERS") << "\n";
    }
    if (std::cin.bad() || !std::cin.eof()) {
        std::cerr << "Input source failure\n";
        return 1;
    }
    std::cout << "Summary: valid=" << validos << ";matches=" << coinciden
              << ";differs=" << difieren << ";format=" << formato << "\n";
    return (difieren > 0 || formato > 0) ? 1 : 0;
}

