#include <iostream>
#include <sstream>
#include <string>

int contar_lineas(const std::string& texto) {
    std::istringstream origen{texto};
    std::string linea;
    int lineas{0};
    while (std::getline(origen, linea)) {
        ++lineas;
    }
    return lineas;
}

int main() {
    std::cout << contar_lineas("") << ':'
              << contar_lineas("\n") << ':'
              << contar_lineas("0 0 0");
    return 0;
}

